				samplesMu.Lock()
				sampledTotal++
				if len(ids) == 0 {
					leaderlessSamples++
					if firstLeaderlessMs < 0 {
						firstLeaderlessMs = ms
					}
					lastLeaderlessMs = ms
				}
				if leader.raft.State() != Leader {
					oldLeaderDownSamples++
				}
				samplesMu.Unlock()
			}
