	snap := NewInmemSnapshotStore()
	if err := BootstrapCluster(conf, store, store, snap, trans, Configuration{Servers: []Server{{Suffrage: Voter, ID: id, Address: addr}}}); err != nil {
		t.Fatalf("BootstrapCluster failed: %v", err)
